import {defaults,validate,clone,demo,parseHistory,analyze,simulate,episodes,wilson} from './model.mjs';
import {chapters} from './book.mjs';
const $=s=>document.querySelector(s),fmt=(n,d=3)=>n==null?'—':n.toLocaleString('vi-VN',{maximumFractionDigits:d}),pct=n=>n==null?'—':fmt(n*100,2)+'%',esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='slide-lab-research-workspace-v1';let rows=demo(),source='Mẫu mô hình · seed cố định · 50.000 vòng',sample=true,result=null,chapter='portfolio',revision=0;
let state={draft:defaults(),saved:[],logs:[],locked:null,trash:[]};
try{const old=JSON.parse(localStorage.getItem(KEY));if(old?.draft){validate(old.draft);old.saved.forEach(validate);state={...state,...old};}}catch{}
if(globalThis.chrome?.storage?.local){const seq=revision;try{const stored=await chrome.storage.local.get(KEY);if(stored[KEY]?.draft&&seq===revision){validate(stored[KEY].draft);stored[KEY].saved.forEach(validate);state={...state,...stored[KEY]};}}catch{}}
function persist(){revision++;let ok=true;try{localStorage.setItem(KEY,JSON.stringify(state));}catch{ok=false;notify('Không lưu được trong trình duyệt. Hãy xuất JSON để giữ chiến thuật.');}if(globalThis.chrome?.storage?.local)chrome.storage.local.set({[KEY]:state}).catch(()=>notify('Không ghi được kho extension. Hãy xuất JSON để sao lưu.'));return ok;}
let noticeTimer;function notify(text){$('#notice').textContent=text;$('#notice').hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').hidden=true,7000);}
function protect(fn){return async(...args)=>{try{await fn(...args);}catch(e){notify(e.message||String(e));}}}
function view(name){document.querySelectorAll('[data-panel]').forEach(p=>p.hidden=p.dataset.panel!==name);document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('selected',b.dataset.view===name));if(name==='library')renderLibrary();if(name==='book')renderBook();}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));
const fields={'strategy-name':'name',bankroll:'bankroll',condition:'condition',gap:'gap','low-count':'lowCount','low-value':'lowValue',horizon:'horizon',exhausted:'exhausted',train:'train',validation:'validation'};
function pull(){for(const [id,key]of Object.entries(fields)){const node=$('#'+id);state.draft[key]=['name','condition','exhausted'].includes(key)?node.value:Number(node.value);}validate(state.draft);return state.draft;}
function renderDraft(){for(const [id,key]of Object.entries(fields))$('#'+id).value=state.draft[key];renderTargets();renderAnalysisOptions();$('#draft-status').textContent='Bản nháp · chỉnh sửa tự lưu';}
function renderTargets(){const host=$('#targets');host.replaceChildren();state.draft.targets.forEach((t,ti)=>{
 const box=document.createElement('div');box.className='target-card';box.innerHTML=`<div class="target-header"><input type="checkbox" aria-label="Bật target ${ti+1}" ${t.enabled?'checked':''}><span>Target ×</span><input type="number" min="1.01" max="4294967000" step="any" aria-label="Hệ số target ${ti+1}" value="${t.target}"><button class="remove-target" aria-label="Xóa target ${ti+1}">Xóa bảng</button></div><div class="step-head"><span>#</span><span>Mức cược</span><span>Số vòng</span><span>Target bậc</span><span>Hành động</span><span></span></div>`;
 box.querySelector('input[type=checkbox]').onchange=e=>{t.enabled=e.target.checked;changed();renderAnalysisOptions();};box.querySelector('.target-header input[type=number]').onchange=protect(e=>{t.target=Number(e.target.value);changed();renderAnalysisOptions();});
 box.querySelector('.remove-target').onclick=()=>{if(state.draft.targets.length===1)return notify('Cần giữ ít nhất một bảng.');state.draft.targets.splice(ti,1);changed();renderTargets();renderAnalysisOptions();};
 t.steps.forEach((s,si)=>{const row=document.createElement('div');row.className='step-row';row.innerHTML=`<span>${si+1}</span><input aria-label="Mức cược bảng ${ti+1} bậc ${si+1}" type="number" step="any" min="0.00000001" value="${s.amount}"><input aria-label="Số vòng bảng ${ti+1} bậc ${si+1}" type="number" min="1" max="100000" value="${s.rounds}"><input aria-label="Target bảng ${ti+1} bậc ${si+1}" type="number" step="any" min="1.01" placeholder="Theo bảng" value="${s.multiplier??''}"><select aria-label="Hành động bảng ${ti+1} bậc ${si+1}"><option ${s.action==='BET'?'selected':''}>BET</option><option ${s.action==='WAIT'?'selected':''}>WAIT</option></select><button aria-label="Xóa bậc ${si+1} bảng ${ti+1}">×</button>`;
 row.querySelectorAll('input').forEach((input,i)=>input.onchange=protect(()=>{const key=['amount','rounds','multiplier'][i];if(key==='multiplier'&&!input.value)delete s.multiplier;else s[key]=Number(input.value);changed();}));row.querySelector('select').onchange=e=>{s.action=e.target.value;changed();};row.querySelector('button').onclick=()=>{if(t.steps.length===1)return notify('Mỗi bảng cần ít nhất một bậc.');t.steps.splice(si,1);changed();renderTargets();};box.append(row);});
 const add=document.createElement('button');add.textContent='＋ Thêm bậc';add.onclick=()=>{if(t.steps.length>=100)return notify('Tối đa 100 bậc.');t.steps.push(clone(t.steps.at(-1)));changed();renderTargets();};box.append(add);host.append(box);
});}
function changed(){result=null;try{pull();persist();$('#draft-status').textContent='Đã giữ bản nháp';}catch(e){$('#draft-status').textContent='Có ô chưa hợp lệ';notify(e.message);}$('#hit-rate').textContent='—';$('#hit-count').textContent='Chưa chạy lại';$('#baseline').textContent='—';$('#interval').replaceChildren();$('#comparisons').replaceChildren();$('#equity-chart').replaceChildren();$('#conclusion').textContent='Cấu hình đã thay đổi. Chạy lại để xem kết quả phù hợp.';$('#run').textContent='▶ Chạy phân tích';renderSplit();}
for(const id of Object.keys(fields))$('#'+id).onchange=changed;
function renderAnalysisOptions(){const select=$('#analysis-target'),old=select.value;select.replaceChildren(...state.draft.targets.filter(t=>t.enabled).sort((a,b)=>a.target-b.target).map(t=>{const o=document.createElement('option');o.value=t.id;o.textContent='x'+fmt(t.target);return o;}));if([...select.options].some(o=>o.value===old))select.value=old;}
function renderSplit(){const c=state.draft,a=Math.floor(rows.length*c.train/100),b=Math.floor(rows.length*c.validation/100);$('#split-line').innerHTML=[['Khám phá',a],['Xác thực',b],['Kiểm tra · thăm dò',rows.length-a-b]].map(([l,n])=>`<div>${l}<b>${fmt(n,0)} vòng</b></div>`).join('');}
function chartCI(ci,rate,base){if(!ci)return '<p class="hint">Chưa có cửa sổ hoàn chỉnh.</p>';const x=v=>40+v*680;return `<svg viewBox="0 0 760 100" role="img" aria-label="Khoảng ước lượng Wilson 95 phần trăm"><line x1="40" y1="65" x2="720" y2="65" stroke="#405675"/>${[0,.25,.5,.75,1].map(v=>`<text x="${x(v)}" y="88" text-anchor="middle">${pct(v)}</text>`).join('')}<line x1="${x(ci[0])}" y1="35" x2="${x(ci[1])}" y2="35" stroke="#ba94ff" stroke-width="5"/><circle cx="${x(rate)}" cy="35" r="7" fill="#ba94ff"/><line x1="${x(base)}" y1="12" x2="${x(base)}" y2="65" stroke="#ffd16a" stroke-width="2" stroke-dasharray="4 4"/><text x="40" y="13">95%: ${pct(ci[0])}–${pct(ci[1])} · từng phép thử</text></svg>`;}
function equityChart(comps){const colors=['#50dfb4','#ffd16a','#ac8afa'],all=comps.flatMap(c=>c.path),lo=Math.min(0,...all),hi=Math.max(.001,...all),scale=v=>120-(v-lo)/(hi-lo)*100;return `<svg viewBox="0 0 760 165" role="img" aria-label="Đường P/L mô phỏng"><line x1="40" y1="${scale(0)}" x2="740" y2="${scale(0)}" stroke="#405675" stroke-dasharray="4 4"/>${comps.map((c,i)=>`<polyline points="${c.path.map((v,j)=>`${40+j/(Math.max(1,c.path.length-1))*700},${scale(v)}`).join(' ')}" fill="none" stroke="${colors[i]}" stroke-width="2"/>`).join('')}${['Cố định','Chờ điều kiện','Bậc cấu hình'].map((l,i)=>`<text x="${40+i*230}" y="151" style="fill:${colors[i]}">● ${l}</text>`).join('')}</svg>`;}
function run(log=true){const c=pull(),t=c.targets.find(t=>t.id===$('#analysis-target').value);if(!t)throw Error('Bật ít nhất một target để phân tích.');result=analyze(rows,c,t.target);const r=result;$('#hit-rate').textContent=pct(r.rate);$('#hit-count').textContent=`${r.hits} / ${r.n} cửa sổ không chồng lặp`;$('#baseline').textContent=pct(r.baseline);$('#interval').innerHTML=chartCI(r.ci,r.rate,r.baseline);$('#conclusion').textContent=(r.n<30?'Mẫu ít: chưa đủ cơ sở kết luận. ':'Kết quả thăm dò; chưa thể kết luận có lợi thế. ')+(sample?'Nguồn là dữ liệu mô hình giả lập. ':'Chưa hiệu chỉnh nhiều phép thử hoặc xác minh tính độc lập của nguồn.');
 $('#comparisons').innerHTML=r.comparisons.map((v,i)=>`<tr><td>${['Cược cố định','Chờ điều kiện','Bậc cấu hình'][i]}${v.halt?'<br><small>'+esc(v.halt)+'</small>':''}</td><td class="${v.profit<0?'negative':'positive'}">${fmt(v.profit)}</td><td>${pct(v.roi)}</td><td>${fmt(v.drawdown)}</td><td>${fmt(v.turnover)}</td><td>${v.wins} / ${v.losses}</td></tr>`).join('');$('#equity-chart').innerHTML=equityChart(r.comparisons);$('#live-target').textContent='x'+fmt(t.target);$('#current-gap').textContent=(r.gap.known?'':'≥ ')+fmt(r.gap.current,0)+' vòng';$('#p90').textContent=fmt(r.gap.p90,0);$('#gap-samples').textContent=fmt(r.gap.completed.length,0);
 if(log){state.logs.unshift({id:crypto.randomUUID(),time:Date.now(),name:c.name,config:clone(c),source,rows:rows.length,sample,target:t.target,windows:r.n,hits:r.hits});state.logs=state.logs.slice(0,100);persist();renderLogs();}renderSplit();}
$('#run').onclick=protect(()=>run());$('#analysis-target').onchange=protect(()=>run(false));
$('#add-target').onclick=protect(()=>{pull();if(state.draft.targets.length>=20)throw Error('Tối đa 20 bảng.');state.draft.targets.push({id:crypto.randomUUID(),enabled:true,target:150,steps:[{amount:.002,rounds:100,action:'BET'}]});changed();renderTargets();renderAnalysisOptions();});
$('#save').onclick=protect(()=>{pull();const saved={...clone(state.draft),id:crypto.randomUUID(),parentId:state.draft.id,savedAt:Date.now()};state.saved.unshift(saved);state.draft=clone(saved);persist();renderCounts();notify('Đã lưu phiên bản mới. Bản đã khóa không đổi.');});
$('#duplicate').onclick=protect(()=>{pull();state.draft={...clone(state.draft),id:crypto.randomUUID(),name:state.draft.name+' · bản sao'};persist();renderDraft();notify('Đã tạo bản nháp độc lập.');});
$('#new').onclick=()=>{state.draft=defaults();persist();renderDraft();changed();};
function renderLibrary(){$('#library').replaceChildren(...state.saved.map(c=>{const card=document.createElement('article');card.className='card library-card';card.innerHTML=`<span class="tag">PHIÊN BẢN ĐÃ LƯU · ${new Date(c.savedAt||Date.now()).toLocaleString('vi-VN')}</span><h2>${esc(c.name)}</h2><p>${c.targets.filter(t=>t.enabled).length} bảng bật · vốn ${fmt(c.bankroll)} · ${esc({gap:'Chờ GAP',low:'Chuỗi thấp',always:'Không chờ'}[c.condition])}</p><p class="hint">${c.targets.map(t=>'x'+fmt(t.target)).join(' · ')}</p><div class="actions"><button data-action="edit">Mở & sửa</button><button data-action="copy">Nhân bản</button><button data-action="delete">Cất vào thùng rác</button></div>`;card.querySelector('[data-action=edit]').onclick=()=>{state.draft=clone(c);persist();renderDraft();view('lab');changed();};card.querySelector('[data-action=copy]').onclick=()=>{state.draft={...clone(c),id:crypto.randomUUID(),name:c.name+' · bản sao'};persist();renderDraft();view('lab');changed();};card.querySelector('[data-action=delete]').onclick=()=>{state.trash.unshift(c);state.saved=state.saved.filter(v=>v.id!==c.id);persist();renderLibrary();renderCounts();};return card;}));if(!state.saved.length)$('#library').innerHTML='<div class="card empty">Chưa có bản đã lưu. Tạo cấu hình rồi chọn “Lưu phiên bản mới”.</div>';if(state.trash.length){const button=document.createElement('button');button.textContent='Khôi phục chiến thuật vừa cất';button.onclick=()=>{state.saved.unshift(state.trash.shift());persist();renderLibrary();renderCounts();};$('#library').append(button);}}
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#export-report').onclick=protect(()=>{if(!result)throw Error('Chạy phân tích trước khi xuất báo cáo.');download('slide-research-report.json',{schema:1,source,sample,time:Date.now(),config:state.draft,result,limitations:['Thăm dò, chưa hiệu chỉnh nhiều cấu hình','Mô hình xác suất không phải dự đoán vòng kế tiếp'],experiments:state.logs});});
$('#export-strategies').onclick=()=>download('slide-research-strategies.json',{schema:1,strategies:state.saved,locked:state.locked});
$('#strategy-file').onchange=protect(async e=>{const file=e.target.files[0];if(!file)return;if(file.size>5e6)throw Error('Tệp chiến thuật tối đa 5 MB.');const data=JSON.parse(await file.text());if(data.schema!==1||!Array.isArray(data.strategies)||data.strategies.length>100)throw Error('Cần tệp chiến thuật Research schema 1, tối đa 100 bản.');data.strategies.forEach(validate);for(const c of data.strategies)state.saved.unshift({...clone(c),id:crypto.randomUUID(),savedAt:Date.now()});persist();renderLibrary();renderCounts();e.target.value='';notify('Đã nhập các chiến thuật. Không thay bản đang khóa.');});
$('#history-file').onchange=protect(async e=>{const file=e.target.files[0];if(!file)return;if(file.size>150e6)throw Error('Tệp lịch sử tối đa 150 MB.');const parsed=parseHistory(JSON.parse(await file.text()));rows=parsed;sample=false;source='Lịch sử nhập: '+file.name;result=null;renderCounts();run(false);e.target.value='';notify('Đã nạp lịch sử vào bộ nhớ trang. Không gửi dữ liệu ra ngoài.');});
$('#load-demo').onclick=()=>{rows=demo();source='Mẫu mô hình · seed cố định · 50.000 vòng';sample=true;renderCounts();protect(()=>run(false))();};
$('#portfolio-preset').onclick=()=>{const c=defaults();c.name='10 target · tham khảo bậc đầu';c.condition='always';c.targets=[90,113,150,250,350,410,450,680,880,1660].map(target=>({id:crypto.randomUUID(),target,enabled:true,steps:[{amount:[680,880,1660].includes(target)?.001:.002,rounds:100,action:'BET'}]}));state.draft=c;persist();renderDraft();view('lab');changed();notify('Đã tạo mẫu bậc đầu. Các bậc thực tế chưa được nhập.');};
$('#lock').onclick=protect(()=>{pull();state.locked={id:crypto.randomUUID(),config:clone(state.draft),start:rows.length,source,sample,anchor:rows.at(-1)?.id,observed:[],time:Date.now(),goal:5000};persist();renderLocked();notify('Đã khóa bản riêng. Mốc đánh giá minh họa: 5.000 vòng mới.');});
$('#advance').onclick=protect(()=>{if(!sample)throw Error('Nguồn nhập không tạo vòng giả. Nạp lại tệp mới để xem lịch sử cập nhật.');if(!state.locked)throw Error('Khóa một bản trước khi thêm vòng mẫu.');rows=demo(rows.length+20);source='Mẫu mô hình · seed cố định · '+fmt(rows.length,0)+' vòng';renderCounts();run(false);renderLocked();});
function renderLocked(){const lock=state.locked;$('#advance').disabled=!sample||!lock;if(!lock){$('#locked-info').textContent='Lưu và khóa một phiên bản để theo dõi giả lập. Chỉnh bản nháp không đổi bản đã khóa.';$('#forward-status').textContent='Không gửi lệnh tới Stake.';return;}$('#locked-info').textContent=lock.config.name+' · '+lock.config.targets.filter(t=>t.enabled).length+' target · khóa '+new Date(lock.time).toLocaleString('vi-VN');if(lock.sample!==sample||(!sample&&lock.source!==source)||rows.length<lock.start){$('#forward-status').textContent='Nguồn hiện tại khác nguồn lúc khóa. Chưa có theo dõi mới phù hợp.';return;}const anchor=lock.observed?.at(-1)?.id||lock.anchor;
 const anchorIndex=rows.findIndex(r=>r.id===anchor);
 if(anchorIndex<0){$('#forward-status').textContent='Mốc đã khóa không còn trong nguồn. Không nối dữ liệu hoặc suy đoán vòng bị thiếu.';return;}
 const extra=rows.slice(anchorIndex+1),remaining=Math.max(0,lock.goal-(lock.observed?.length||0));
 if(extra.length&&remaining){lock.observed=[...(lock.observed||[]),...extra.slice(0,remaining)];persist();}
 const fresh=lock.observed||[],sim=simulate(fresh,lock.config);$('#forward-status').textContent=`${fresh.length} / ${lock.goal} vòng mới · P/L giả lập ${fmt(sim.profit)} · W/L ${sim.wins}/${sim.losses}. Chốt mốc trước khi diễn giải.`;}
function renderCounts(){$('#round-count').textContent=fmt(rows.length,0);$('#segment-count').textContent=fmt(1+rows.filter(r=>r.gapBefore).length,0);$('#saved-count').textContent=state.saved.length;$('#source-badge').textContent=sample?'DỮ LIỆU MẪU · KHÔNG CƯỢC THẬT':'LỊCH SỬ ĐÃ NHẬP · CHỈ MÔ PHỎNG';$('#data-provenance').textContent=source+' · '+fmt(rows.length,0)+' vòng. '+(sample?'Sinh từ mô hình xác suất, không lấy từ tài khoản.':'Chưa xác minh nguồn với server game.');renderSplit();renderLocked();}
function renderLogs(){$('#experiment-log').replaceChildren(...state.logs.slice(0,8).map(l=>{const box=document.createElement('div');box.textContent=`${l.name} · x${fmt(l.target)} · ${l.hits}/${l.windows} cửa sổ · ${l.sample?'Mẫu':'Nhập'} · ${new Date(l.time).toLocaleTimeString('vi-VN')}`;return box;}));if(!state.logs.length)$('#experiment-log').textContent='Chưa có lần thử đã lưu.';}
function renderBook(){$('#book-toc').innerHTML='<h2>Mục lục · 8 chương</h2>';chapters.forEach(c=>{const b=document.createElement('button');b.textContent=c.title;b.classList.toggle('selected',c.id===chapter);b.onclick=()=>{chapter=c.id;renderBook();};$('#book-toc').append(b);});const c=chapters.find(c=>c.id===chapter);$('#book-content').innerHTML=`<span class="eyebrow">${c.tag}</span><h2>${c.title}</h2>${c.html}<p class="hint">Biên soạn ngày 09/10/2026 · Ví dụ và mô phỏng không chứng minh lợi nhuận tương lai.</p>`;}
document.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>{chapter=b.dataset.chapter;view('book');});$('#print-book').onclick=()=>window.print();
if(sample&&state.locked?.sample&&state.locked.observed?.length){rows=demo(Math.max(50000,state.locked.start+state.locked.observed.length));source='Mẫu mô hình · seed cố định · '+fmt(rows.length,0)+' vòng';}
// When opened inside the extension, offer its observed archive automatically.
if(globalThis.chrome?.storage?.local){try{const saved=await chrome.storage.local.get('slide-lab-round-archive-v1'),archive=saved['slide-lab-round-archive-v1'];if(archive?.rows?.length){rows=parseHistory(archive.rows);source='Kho quan sát của extension · bản chụp khi mở trang';sample=false;}}catch(e){notify('Chưa đọc được kho vòng của extension: '+e.message);}}
if(globalThis.chrome?.storage?.onChanged)chrome.storage.onChanged.addListener((changes,area)=>{
 if(area!=='local'||sample||!source.startsWith('Kho quan sát của extension')||!changes['slide-lab-round-archive-v1']?.newValue?.rows)return;
 try{rows=parseHistory(changes['slide-lab-round-archive-v1'].newValue.rows);renderCounts();run(false);}catch(e){notify('Chưa cập nhật được nguồn: '+e.message);}
});
renderDraft();renderCounts();renderLogs();renderBook();protect(()=>run(false))();
